using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Models;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments for dispatchers
        group.MapGet("/all", async (ApplicationDbContext db, HttpContext http) =>
        {
            var user = http.User;
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => MapToDto(s))
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Get shipments for the current customer
        group.MapGet("/my", async (ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext http) =>
        {
            var userId = userManager.GetUserId(http.User);
            var shipments = await db.Shipments
                .Where(s => s.CustomerId == userId)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => MapToDto(s))
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Track a shipment by tracking number (accessible to any authenticated user)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.Ok(new TrackingResult { Found = false, ErrorMessage = "Shipment not found." });

            return Results.Ok(new TrackingResult { Found = true, Shipment = MapToDto(shipment) });
        });

        // Update shipment status (dispatchers only)
        group.MapPost("/update-status", async (UpdateShipmentStatusRequest request, ApplicationDbContext db, HttpContext http) =>
        {
            if (!http.User.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(request.ShipmentId);
            if (shipment is null)
                return Results.NotFound();

            if (Enum.TryParse<ShipmentStatus>(request.NewStatus, out var newStatus))
            {
                shipment.Status = newStatus;
                if (!string.IsNullOrWhiteSpace(request.Notes))
                    shipment.Notes = request.Notes;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.ActualDelivery = DateTime.UtcNow;

                await db.SaveChangesAsync();
                return Results.Ok(MapToDto(shipment));
            }

            return Results.BadRequest("Invalid status value.");
        });

        // Create a new shipment (dispatchers only)
        group.MapPost("/create", async (CreateShipmentRequest request, ApplicationDbContext db, HttpContext http, UserManager<ApplicationUser> userManager) =>
        {
            if (!http.User.IsInRole("Dispatcher"))
                return Results.Forbid();

            var dispatcherId = userManager.GetUserId(http.User);

            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = request.EstimatedDelivery,
                RecipientName = request.RecipientName,
                RecipientEmail = request.RecipientEmail,
                CustomerId = request.CustomerId ?? string.Empty,
                DispatcherId = dispatcherId,
                Notes = request.Notes ?? string.Empty
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            return Results.Ok(MapToDto(shipment));
        });
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Notes = s.Notes
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpper()}";
    }
}

public class CreateShipmentRequest
{
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public DateTime? EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string RecipientEmail { get; set; } = string.Empty;
    public string? CustomerId { get; set; }
    public string? Notes { get; set; }
}

