@code {
    private string trackingNumber = string.Empty;
    private TrackingResult? result;
    private string? errorMessage;
    private bool isLoading;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        result = null;

        try
        {
            result = await Http.GetFromJsonAsync<TrackingResult>($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (result?.Found == false)
            {
                errorMessage = result.ErrorMessage ?? "Shipment not found. Please check the tracking number.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error tracking shipment: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static int GetProgressPercentage(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Cancelled" => 100,
        _ => 0
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

