            shipments = await Http.GetFromJsonAsync<ShipmentDto[]>("/api/shipments/all");
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(int shipmentId, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus)) return;

        try
        {
            var request = new UpdateShipmentStatusRequest
            {
                ShipmentId = shipmentId,
                NewStatus = newStatus
            };
            var response = await Http.PostAsJsonAsync("/api/shipments/update-status", request);
            if (response.IsSuccessStatusCode)
            {
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to update status.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error: {ex.Message}";
        }
    }

    private async Task CreateShipment()
    {
        try
        {
            var response = await Http.PostAsJsonAsync("/api/shipments/create", newShipment);
            if (response.IsSuccessStatusCode)
            {
                newShipment = new();
                showCreateForm = false;
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to create shipment.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error: {ex.Message}";
        }
    }

    private void ShowCreateForm() => showCreateForm = !showCreateForm;

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

