@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@rendermode InteractiveWebAssembly
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>Track a Shipment</h1>

<div class="row mb-4">
    <div class="col-md-8 col-lg-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260101-A1B2C3D4)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (result?.Found == true && result.Shipment is not null)
{
    var shipment = result.Shipment;
    <div class="card">
        <div class="card-header bg-primary text-white">
            <h5 class="mb-0">Shipment: @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h6>Shipment Details</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7"><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span></dd>

                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>

                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <h6>Delivery Information</h6>
                    <dl class="row">
                        <dt class="col-sm-5">Created</dt>
                        <dd class="col-sm-7">@shipment.CreatedAt.ToString("MMM dd, yyyy")</dd>

                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <dt class="col-sm-5">Est. Delivery</dt>
                            <dd class="col-sm-7">@shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</dd>
                        }

                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt class="col-sm-5">Delivered On</dt>
                            <dd class="col-sm-7 text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")</dd>
                        }
                    </dl>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <div class="mt-3">
                    <h6>Notes</h6>
                    <p class="text-muted">@shipment.Notes</p>
                </div>
            }

            <!-- Status progress bar -->
            <div class="mt-4">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(shipment.Status)%"
                         aria-valuenow="@GetProgressPercentage(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(shipment.Status)
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private TrackingResult? result;
    private string? errorMessage;
    private bool isLoading;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        result = null;

        try
        {
            result = await Http.GetFromJsonAsync<TrackingResult>($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (result?.Found == false)
            {
                errorMessage = result.ErrorMessage ?? "Shipment not found. Please check the tracking number.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error tracking shipment: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private static int GetProgressPercentage(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Cancelled" => 100,
        _ => 0
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

